hooks.command:
$input_json = [Console]::In.ReadToEnd() | ConvertFrom-Json
$path = $input_json.tool_input.file_path
if ($path -and ($path -match '(^|[\\/])\.env$') -and ($path -notmatch '\.env\.example$')) {
  $output = @{ hookSpecificOutput = @{ hookEventName = 'PreToolUse'; permissionDecision = 'deny'; permissionDecisionReason = '.env manuell bearbeiten -- nicht ueber Claude.' } }
  $output | ConvertTo-Json -Depth 5 -Compress
}

$input_json = [Console]::In.ReadToEnd() | ConvertFrom-Json
$path = $input_json.tool_input.file_path
if (-not $path) { exit 0 }
$norm = $path -replace '\\', '/'
$reason = $null
if ($norm -match '/sheets/data/[^/]+\.json$') {
  $reason = 'sheets/data/*.json wird generiert -- sheets/layouts/*.json bearbeiten und .venv/Scripts/python.exe -m sheets.layout ausfuehren (AGENTS.md).'
}
if ($reason) {
  $output = @{ hookSpecificOutput = @{ hookEventName = 'PreToolUse'; permissionDecision = 'deny'; permissionDecisionReason = $reason } }
  $output | ConvertTo-Json -Depth 5 -Compress
}
